import datetime
from typing import Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.tracer import tracer


class OpenStoreMethods(BaseClient):
    """
    Методы группы 'Store' из https://im-docs.corp.mail.ru/
    """

    @tracer.start_as_current_span("openstore.openstore_filespackinfowithmeta")
    def openstore_filespackinfowithmeta(self, pack_id: Optional[int] = None, store_id: Optional[str] = None):
        if pack_id is None and store_id is None:
            raise ValueError("pack_id OR store_id must be not None")

        return self.get(
            path="store/openstore/filespackinfowithmeta",
            id=pack_id,
            store_id=store_id,
            aimsid=self.aimsid,
            client=self.client_name,
            f="json",
            k=self.devId,
            lang="ru-ru",
            r=self.getReqId(),
            platform="mac",
            ts=int(datetime.datetime.now().timestamp()),
        )
